mapper.select:
        SELECT 
			count(*) 
		FROM 
			REP_REVEAL
		WHERE
			REP_ID = #{repId,jdbcType=VARCHAR}

					AND IF(!ISNULL(PRODID),PRODID,'0') in

						#{item}


		AND IF(!ISNULL(DATE_FORMAT(START_DATE,'%Y-%m-%d')),DATE_FORMAT(START_DATE,'%Y-%m-%d'),'0') = #{startDate,jdbcType=VARCHAR}
		AND IF(!ISNULL(DATE_FORMAT(END_DATE,'%Y-%m-%d')),DATE_FORMAT(END_DATE,'%Y-%m-%d'),'0') = #{endDate,jdbcType=VARCHAR}
		AND STATUS='E'

mapper.update:
    	UPDATE
   			REP_REVEAL
		SET STATUS = 'D'
		,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
		,UPDATE_TIME = NOW()
		WHERE
			REP_ID = #{repId,jdbcType=VARCHAR}
		AND PRODID = #{portnum,jdbcType=VARCHAR}
		AND IF(!ISNULL(DATE_FORMAT(START_DATE,'%Y-%m-%d')),DATE_FORMAT(START_DATE,'%Y-%m-%d'),'0') = #{startDate,jdbcType=VARCHAR}
		AND IF(!ISNULL(DATE_FORMAT(END_DATE,'%Y-%m-%d')),DATE_FORMAT(END_DATE,'%Y-%m-%d'),'0') = #{endDate,jdbcType=VARCHAR}
		AND STATUS='E'
